 @Test public void sharedQuarantineBlocksPrecreatedOtherDirection(){var shared=new ReviewShizukuSwipeActor.ProcessFence();Fake first=new Fake(),second=new Fake();first.closeThrows=true;var up=ReviewShizukuSwipeActor.fixtureProcess(first,shared);var down=ReviewShizukuSwipeActor.fixtureProcess(second,shared,ReviewShizukuSwipeActor.Direction.DOWN);up.swipe(TARGET,new Gate());var t=new ReviewShizukuSwipeActor.SwipeTarget(1080,2400,0,ReviewShizukuSwipeActor.Direction.DOWN);var r=down.swipe(t,gateFor(t));assertEquals(ReviewShizukuSwipeActor.Reason.PREFLIGHT_UNAVAILABLE,r.reason());assertFalse(r.invocationAttempted());assertEquals(0,second.opens);try{ReviewShizukuSwipeActor.fixtureProcess(new Fake(),shared,ReviewShizukuSwipeActor.Direction.DOWN);fail();}catch(SecurityException expected){}}
