 @Test public void v43PreservesSyntheticUpAndDownFixtureCoverage(){assertEquals(ReadOnlyCheckpoint.UI_BOUND_POINTS_V53,ReadOnlyCheckpoint.CURRENT);Fake up=new Fake(),down=new Fake();var downTarget=new ReviewShizukuSwipeActor.SwipeTarget(1080,2400,0,ReviewShizukuSwipeActor.Direction.DOWN);assertTrue(new ReviewShizukuSwipeActor(up).swipe(TARGET,new Gate()).commandExitZero());assertTrue(new ReviewShizukuSwipeActor(down,ReviewShizukuSwipeActor.Direction.DOWN).swipe(downTarget,gateFor(downTarget)).commandExitZero());assertEquals(1,up.invocations);assertEquals(1,down.invocations);}
